Slab method for ray/segment vs AABB:
```
function lineRect(px, py, x, y, minX, maxX, minY, maxY) {
  let tenter = 0.0, texit = 1.0;
  let dx = x - px, dy = y - py;

  // x
  if (dx === 0) {
    if (px < minX || px > maxX) return null;
  } else {
    let t1 = (minX - px) / dx;
    let t2 = (maxX - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tenter = Math.max(tenter, t1);
    texit = Math.min(texit, t2);
    if (tenter > texit) return null;
  }
  // y
  if (dy === 0) {
    if (py < minY || py > maxY) return null;
  } else {
    let t1 = (minY - py) / dy;
    let t2 = (maxY - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tenter = Math.max(tenter, t1);
    texit = Math.min(texit, t2);
    if (tenter > texit) return null;
  }
  return tenter;
}
```

