```
function sweptEntry(prevX, prevY, x, y, brick, r) {
  const minX = brick.x - r, maxX = brick.x + brick.w + r;
  const minY = brick.y - r, maxY = brick.y + brick.h + r;
  const dx = x - prevX, dy = y - prevY;
  let tEnter = 0, tExit = 1;

  // X slab
  if (dx === 0) {
    if (prevX < minX || prevX > maxX) return null;
  } else {
    let t1 = (minX - prevX) / dx;
    let t2 = (maxX - prevX) / dx;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }
  // Y slab
  if (dy === 0) {
    if (prevY < minY || prevY > maxY) return null;
  } else {
    let t1 = (minY - prevY) / dy;
    let t2 = (maxY - prevY) / dy;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }
  if (tEnter < 0) tEnter = 0; // started inside
  if (tEnter > 1) return null;
  return tEnter;
}
```

