```
// Resolves (detects + bounces) the ball's brick collision for one step.
// `prevX/prevY are the ball's position at the START of the move, so the path
// is swept (see #1: tunnelling) rather than only checking the end position.
// Returns the brick hit (earliest along the path), or null. Mutates ball
// (velocity flip + push-out). Only ONE brick is handled per call — that keeps
// a seam hit from flipping the velocity twice (see #1: neighbours).
export function resolveBallBrick(ball, prevX, prevY, bricks) {
  let hit = null;
  let bestT = Infinity;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const t = sweptEntry(prevX, prevY, ball.x, ball.y, brick, ball.r);
    if (t === null || t > bestT) continue;
    bestT = t;
    hit = brick;
  }
  if (!hit) return null;

  // Reposition the ball to the first contact point (push-out), then bounce.
  if (bestT >= 0 && bestT <= 1) {
    ball.x = prevX + (ball.x - prevX) * bestT;
    ball.y = prevY + (ball.y - prevY) * bestT;
  }
  bounceOff(ball, hit);
  return hit;
}
```

